-- New Jersey, both batches.
--
-- Nothing to drop. No slug collisions across all 1,475 existing rows, nothing
-- within 600 metres of the nine New Jersey stops already held, and no
-- duplicates between the two halves. That is the first hundred-stop batch to
-- come through entirely clean.
--
-- Better sourced than most, too: the New Jersey DEP and the Park Service
-- account for a good share of it, so most of these link out to something
-- useful rather than being credited to a travel guide.
--
-- New Jersey completes the block. Virginia up to Vermont and west to Michigan
-- is now continuous.
--
-- 100 stops, every one with a source.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, website, timezone, verified_at)
values
  ('Sterling Hill Mining Museum', 'sterling-hill-mining-museum', 'museums', 41.08344, -74.60426, 'Ogdensburg', 'NJ', 'An underground zinc mine has been transformed into one of New Jersey''s strangest geology museums. Tours descend into the mine and pass the fluorescent Rainbow Tunnel, while the surface museum preserves an enormous collection of glowing minerals from the famous Franklin-Sterling Hill mining district.', 'limited', 'https://sterlinghillminingmuseum.org/', null, 'America/New_York', now()),
  ('The Paranormal Museum', 'the-paranormal-museum', 'haunted', 40.21596, -74.01142, 'Asbury Park', 'NJ', 'This small museum inside Paranormal Books & Curiosities is devoted to ghosts, legends, cursed objects and other unexplained material. Its collection includes haunted dolls, Ouija boards and rotating exhibits, with access generally through scheduled docent-led tours.', 'limited', 'https://visitnj.org/paranormal-museum-paranormal-books-curiosities', null, 'America/New_York', now()),
  ('Lucy the Elephant', 'lucy-the-elephant', 'roadside-oddities', 39.32084, -74.51159, 'Margate City', 'NJ', 'Built in 1881, Lucy is a six-story elephant-shaped building overlooking the Jersey Shore and one of America''s oldest surviving pieces of novelty architecture. Visitors can tour the interior and climb to the howdah on her back during scheduled operating hours.', 'limited', 'https://lucytheelephant.org/', null, 'America/New_York', now()),
  ('Northlandz', 'northlandz', 'museums', 40.5171, -74.81933, 'Raritan Township', 'NJ', 'This enormous indoor model-railroad world contains miles of track, hundreds of bridges, miniature cities and an almost overwhelming amount of handmade scenery. The sprawling attraction feels less like a conventional train layout and more like walking around an invented miniature country.', 'open', 'https://northlandz.com/', null, 'America/New_York', now()),
  ('Insectropolis', 'insectropolis', 'museums', 40.01493, -74.21631, 'Toms River', 'NJ', 'New Jersey''s "Bugseum" is devoted entirely to insects and other arthropods, with live specimens, preserved collections and interactive displays. Scheduled touch presentations give visitors a chance to meet some of the museum''s stranger living residents.', 'limited', 'https://insectropolis.com/', null, 'America/New_York', now()),
  ('Grounds For Sculpture', 'grounds-for-sculpture', 'roadside-oddities', 40.23679, -74.71889, 'Hamilton Township', 'NJ', 'Hundreds of large-scale sculptures are scattered through landscaped gardens, ponds and wooded paths at this 42-acre art park. Some installations recreate famous paintings as life-size three-dimensional scenes, producing deliberately surreal encounters around the grounds.', 'limited', 'https://www.groundsforsculpture.org/', null, 'America/New_York', now()),
  ('Battleship New Jersey', 'battleship-new-jersey', 'museums', 39.9401, -75.13196, 'Camden', 'NJ', 'The USS New Jersey, one of the most decorated battleships in U.S. history, is preserved as a floating museum on the Delaware River. Visitors can explore gun turrets, crew spaces, command areas and other sections of the enormous Iowa-class warship.', 'open', 'https://www.battleshipnewjersey.org/', null, 'America/New_York', now()),
  ('Absecon Lighthouse', 'absecon-lighthouse', 'weird-history', 39.36633, -74.41415, 'Atlantic City', 'NJ', 'First lit in 1857, Absecon Lighthouse is New Jersey''s tallest lighthouse and contains a 228-step climb to the lantern room. The preserved keeper''s complex provides an unusual historic counterpoint to Atlantic City''s casinos and boardwalk attractions.', 'open', 'https://abseconlighthouse.org/', null, 'America/New_York', now()),
  ('Thomas Edison Memorial Tower', 'thomas-edison-memorial-tower', 'roadside-oddities', 40.56306, -74.33889, 'Edison', 'NJ', 'A 131-foot Art Deco tower topped by an enormous light bulb marks the site of Thomas Edison''s Menlo Park laboratory. The nearby museum interprets the experiments conducted here, including work that helped develop recorded sound and practical electric lighting.', 'limited', 'https://www.menloparkmuseum.org/', null, 'America/New_York', now()),
  ('Morris Museum — Mechanical Music and Automata Collection', 'morris-museum-mechanical-music-and-automata-collection', 'museums', 40.79561, -74.448, 'Morris Township', 'NJ', 'The Morris Museum houses the Murtogh D. Guinness Collection of mechanical musical instruments and automata. Self-playing organs, music boxes and elaborate moving figures preserve a world of entertainment machinery built before electronic media.', 'open', 'https://morrismuseum.org/', null, 'America/New_York', now()),
  ('Silverball Retro Arcade', 'silverball-retro-arcade', 'museums', 40.2208, -73.99998, 'Asbury Park', 'NJ', 'Rows of playable pinball machines and classic arcade games fill this boardwalk museum, with machines spanning many decades of amusement history. Admission is time-based rather than coin-operated, so the collection functions as both museum and working arcade.', 'open', 'https://www.silverballmuseum.com/asbury-park/', null, 'America/New_York', now()),
  ('Space Farms Zoo & Museum', 'space-farms-zoo-museum', 'museums', 41.20925, -74.69494, 'Wantage Township', 'NJ', 'This family-run complex combines a zoo with nine buildings packed with antique cars, motorcycles, farm equipment, minerals and other collected objects. The unusually broad museum collection makes Space Farms much stranger than a standard animal park; its public season runs primarily from spring through fall.', 'limited', 'https://spacefarms.com/', null, 'America/New_York', now()),
  ('White Mana Diner', 'white-mana-diner', 'roadside-oddities', 40.74706, -74.06157, 'Jersey City', 'NJ', 'This tiny stainless-steel diner began as a futuristic building displayed at the 1939 New York World''s Fair before being moved to Jersey City. Its compact circular form and counter-only interior preserve a distinctive piece of early roadside diner architecture.', 'open', 'https://www.atlasobscura.com/places/white-mana-diner', null, 'America/New_York', now()),
  ('Holsten''s — The Sopranos Final Booth', 'holstens-the-sopranos-final-booth', 'weird-history', 40.82828, -74.18663, 'Bloomfield', 'NJ', 'Holsten''s old-fashioned ice-cream parlor became television history when its corner booth was used for the final scene of The Sopranos. The restaurant remains an active local business and openly acknowledges its connection with the famously ambiguous ending.', 'open', 'https://www.atlasobscura.com/places/holstens', null, 'America/New_York', now()),
  ('Bell Works — Former Bell Labs Holmdel Complex', 'bell-works-former-bell-labs-holmdel-complex', 'weird-history', 40.36433, -74.16606, 'Holmdel Township', 'NJ', 'Eero Saarinen''s enormous mirrored Bell Labs building housed research that helped transform telecommunications and computing. The former laboratory has been reused as the publicly accessible Bell Works complex while retaining its vast futuristic atrium and distinctive architecture.', 'open', 'https://bell.works/new-jersey/', null, 'America/New_York', now()),
  ('Batsto Village', 'batsto-village', 'weird-history', 39.64461, -74.64692, 'Washington Township', 'NJ', 'More than 40 surviving structures preserve a Pine Barrens industrial village built around ironmaking and later glass production. The grounds are open daily, with an 1852 post office, sawmill, mansion and other buildings forming a remarkably intact historic settlement.', 'open', 'https://dep.nj.gov/parksandforests/state-park/batsto-village/', null, 'America/New_York', now()),
  ('Waterloo Village', 'waterloo-village', 'weird-history', 40.91556, -74.75611, 'Byram Township', 'NJ', 'This preserved canal village grew beside the Morris Canal and contains historic homes, shops, a mill and other nineteenth-century structures. The grounds are open from dawn to dusk, while interior tours and interpretive buildings follow a more limited seasonal schedule.', 'open', 'https://dep.nj.gov/parksandforests/state-park/waterloo-village/', null, 'America/New_York', now()),
  ('Burlington County Prison Museum', 'burlington-county-prison-museum', 'museums', 39.9966, -74.78931, 'Mount Holly', 'NJ', 'Designed by Robert Mills and opened in 1811, this stone jail remained in use for more than 150 years. Cells, corridors, graffiti and execution-related history remain inside, and the building has also developed a strong reputation in local ghost lore.', 'limited', 'https://www.co.burlington.nj.us/954/Prison-Museum', null, 'America/New_York', now()),
  ('Proprietary House', 'proprietary-house', 'haunted', 40.50341, -74.2693, 'Perth Amboy', 'NJ', 'Built in the 1760s, this Georgian mansion served as the home of William Franklin, New Jersey''s last royal governor and Benjamin Franklin''s Loyalist son. The restored house is open for scheduled tours and has accumulated long-running reports of apparitions and unexplained activity.', 'limited', 'https://www.theproprietaryhouse.org/', null, 'America/New_York', now()),
  ('Red Mill Museum Village', 'red-mill-museum-village', 'museums', 40.63715, -74.914, 'Clinton', 'NJ', 'The striking red mill beside the South Branch Raritan River operated in several industrial roles before becoming the centerpiece of a historical museum complex. More than a dozen buildings and thousands of artifacts preserve the site''s industrial and local history.', 'limited', 'https://theredmill.org/', null, 'America/New_York', now()),
  ('Ringwood Manor', 'ringwood-manor', 'weird-history', 41.14444, -74.25278, 'Ringwood', 'NJ', 'This sprawling historic estate is tied to the iron-industry families who controlled large areas of northern New Jersey. The mansion contains layered collections from generations of owners, while the surrounding state-park grounds include cemeteries, outbuildings and remnants of the iron community.', 'limited', 'https://dep.nj.gov/parksandforests/state-park/ringwood-manor/', null, 'America/New_York', now()),
  ('Seabrook-Wilson House — The Spy House', 'seabrook-wilson-house-the-spy-house', 'haunted', 40.43923, -74.09273, 'Middletown Township', 'NJ', 'This eighteenth-century house overlooking Sandy Hook Bay is popularly known as the Spy House because of Revolutionary War stories attached to the property. It has also become one of the Jersey Shore''s better-known haunted-house legends and now serves as a public activity and history center.', 'limited', 'https://www.monmouthcountyparks.com/page.aspx?ID=2524', null, 'America/New_York', now()),
  ('''War of the Worlds'' Martian Landing Site Monument', 'war-of-the-worlds-martian-landing-site-monument', 'ufos', 40.31274, -74.60509, 'West Windsor Township', 'NJ', 'A bronze monument in Van Nest Park marks the fictional Martian landing site from Orson Welles''s famous 1938 War of the Worlds radio broadcast. Interpretive signs explain how the realistic program convinced some listeners that an alien invasion was actually unfolding in New Jersey.', 'open', 'https://www.roadsideamerica.com/story/2749', null, 'America/New_York', now()),
  ('Lucille''s Jersey Devil Statue', 'lucilles-jersey-devil-statue', 'cryptids', 39.7426, -74.3701, 'Warren Grove', 'NJ', 'A winged Jersey Devil figure stands outside Lucille''s Luncheonette along Route 539 in the Pine Barrens. The restaurant embraces local Pine Barrens folklore, making the sculpture a useful physical stop for travelers following the legend of the Leeds Devil.', 'roadside', 'https://www.lucillescountrycooking.com/', null, 'America/New_York', now()),
  ('Wreck of the SS Atlantus', 'wreck-of-the-ss-atlantus', 'weird-history', 38.94434, -74.97206, 'Lower Township', 'NJ', 'The remains of a World War I-era concrete ship sit just offshore from Sunset Beach. The Atlantus broke loose during a storm in 1926 and became permanently stranded, leaving a slowly collapsing piece of experimental shipbuilding visible from shore.', 'open', 'https://www.atlasobscura.com/places/ss-atlantus', null, 'America/New_York', now()),
  ('Menz Restaurant & Bar Oddities', 'menz-restaurant-bar-oddities', 'roadside-oddities', 39.03737, -74.91993, 'Rio Grande', 'NJ', 'Menz surrounds diners with decades of accumulated roadside kitsch, taxidermy and unusual objects. Among its best-known curiosities are a two-headed calf and an eccentric statue honoring the restaurant''s one-legged founder.', 'open', 'https://www.roadsideamerica.com/story/2023', null, 'America/New_York', now()),
  ('Boardwalk Hall Auditorium Organ', 'boardwalk-hall-auditorium-organ', 'museums', 39.35361, -74.43861, 'Atlantic City', 'NJ', 'Hidden inside Jim Whelan Boardwalk Hall is an enormous pipe organ built with more than 30,000 pipes and designed to fill the gigantic auditorium without electronic amplification. Restoration work continues, and public access is mainly through scheduled recitals, tours and events.', 'limited', 'https://www.boardwalkorgans.org/', null, 'America/New_York', now()),
  ('SS Morro Castle Memorial', 'ss-morro-castle-memorial', 'weird-history', 40.22355, -73.99904, 'Asbury Park', 'NJ', 'A memorial near the Asbury Park waterfront remembers the victims of the SS Morro Castle disaster, a 1934 passenger-ship fire that killed more than 130 people offshore. The burned ship eventually grounded near the city and became a grim temporary tourist spectacle.', 'open', 'https://www.atlasobscura.com/places/morro-castle-monument', null, 'America/New_York', now()),
  ('World War II Lookout Tower', 'world-war-ii-lookout-tower', 'weird-history', 38.94343, -74.96699, 'Lower Township', 'NJ', 'Fire Control Tower No. 23 was part of the coastal-defense system protecting the Delaware Bay during World War II. The restored concrete tower now contains interpretive exhibits and can be climbed during seasonal public hours for views across Cape May''s shoreline.', 'limited', 'https://www.capemaymac.org/experience/world-war-ii-tower/', null, 'America/New_York', now()),
  ('Big Rusty', 'big-rusty', 'roadside-oddities', 39.97618, -74.82632, 'Hainesport Township', 'NJ', 'Danish artist Thomas Dambo built this roughly 20-foot troll from recycled materials collected around a former industrial property. Big Rusty crouches beside the remains of an old structure and has become the anchor for Burlington County''s expanded public Troll Trek.', 'open', 'https://www.burlingtoncountynj.gov/2076/Troll-Trek', null, 'America/New_York', now()),
  ('Tear Drop Memorial', 'tear-drop-memorial', 'roadside-oddities', 40.66377, -74.06984, 'Bayonne', 'NJ', 'Officially titled To the Struggle Against World Terrorism, this nearly 100-foot monument consists of a split steel tower holding a huge stainless-steel teardrop. The Russian-designed 9/11 memorial stands on the Bayonne waterfront facing New York Harbor.', 'open', 'https://www.atlasobscura.com/places/tear-drop-memorial', null, 'America/New_York', now()),
  ('Doo Wop Experience Museum and Neon Sign Garden', 'doo-wop-experience-museum-and-neon-sign-garden', 'museums', 38.98281, -74.8179, 'Wildwood', 'NJ', 'This seasonal museum preserves Wildwood''s exuberant 1950s and 1960s motel culture through neon signs, furniture, architecture and pop-culture artifacts. Its outdoor Neon Sign Garden contains restored signs rescued from demolished or remodeled shore motels.', 'limited', 'https://www.doowopusa.org/the-museum', null, 'America/New_York', now()),
  ('Old Barracks Museum', 'old-barracks-museum', 'museums', 40.21988, -74.76865, 'Trenton', 'NJ', 'Built in 1758 during the French and Indian War, these military barracks later housed troops during the American Revolution. The surviving complex now interprets eighteenth-century soldier life and Trenton''s role in the Revolutionary War.', 'limited', 'https://www.barracks.org/', null, 'America/New_York', now()),
  ('New Jersey State Police Museum & Learning Center', 'new-jersey-state-police-museum-learning-center', 'museums', 40.26293, -74.83911, 'Ewing Township', 'NJ', 'The State Police museum preserves uniforms, vehicles, forensic material and evidence associated with major New Jersey cases. Its best-known collection covers the Lindbergh kidnapping investigation, including artifacts and investigative material from one of America''s most famous crimes.', 'limited', 'https://www.nj.gov/njsp/about/museum.shtml', null, 'America/New_York', now()),
  ('Hadrosaurus Foulkii Discovery Site', 'hadrosaurus-foulkii-discovery-site', 'weird-history', 39.9102, -75.02857, 'Haddonfield', 'NJ', 'A small wooded ravine marks the location where bones of Hadrosaurus foulkii were uncovered in 1858. The find became one of the first nearly complete dinosaur skeletons discovered and scientifically described in North America.', 'open', 'https://www.atlasobscura.com/places/hadrosaurus-foulkii-leidy-site', null, 'America/New_York', now()),
  ('Devil''s Tower', 'devils-tower', 'folklore', 40.93381, -73.93322, 'Alpine', 'NJ', 'This stone tower was built in the early twentieth century as part of an estate near the Palisades. Local legend claims the ghost of the owner''s wife haunts the tower and that driving around it backward can summon her, but the structure is on private property and should only be viewed from the public road.', 'roadside', 'https://www.atlasobscura.com/places/devils-tower-alpine-new-jersey', null, 'America/New_York', now()),
  ('Thomas Edison Concrete Houses', 'thomas-edison-concrete-houses', 'roadside-oddities', 40.8378, -74.2119, 'Montclair', 'NJ', 'Thomas Edison experimented with a system for pouring entire houses from concrete as an inexpensive, durable form of mass housing. Several examples survive in Montclair, but they are private residences and should be appreciated only from public streets.', 'private', 'https://www.atlasobscura.com/places/thomas-edisons-concrete-houses', null, 'America/New_York', now()),
  ('Cookie Jar House', 'cookie-jar-house', 'roadside-oddities', 39.84178, -75.07808, 'Glendora', 'NJ', 'This round novelty house was constructed to resemble an enormous cookie jar, complete with a lid-like roof. It remains a private residence, so OddWay travelers should view the unusual architecture only from public roads without entering the property.', 'private', 'https://www.atlasobscura.com/places/cookie-jar-house', null, 'America/New_York', now()),
  ('Deserted Village of Feltville', 'deserted-village-of-feltville', 'weird-history', 40.6818, -74.3874, 'Berkeley Heights', 'NJ', 'Stone houses and other structures survive from a nineteenth-century mill community later reinvented as the summer resort Glenside Park. The abandoned settlement is preserved within Watchung Reservation and can be explored legally from public trails.', 'open', 'https://ucnj.org/parks-recreation/deserted-village/', null, 'America/New_York', now()),
  ('Hindenburg Crash Site', 'hindenburg-crash-site', 'weird-history', 40.03171, -74.32235, 'Lakehurst', 'NJ', 'The German airship Hindenburg caught fire while attempting to land at Lakehurst in 1937, killing 36 people and helping end the era of passenger zeppelins. The marked crash site lies inside an active military installation, so visitors can only access it through approved tours and base procedures.', 'limited', 'https://www.jbmdl.jb.mil/About-Us/History/Hindenburg/', null, 'America/New_York', now()),
  ('Ghost Lake on Shades of Death Road', 'ghost-lake-on-shades-of-death-road', 'folklore', 40.92532, -74.89997, 'Knowlton Township', 'NJ', 'This small lake beside the famously named Shades of Death Road developed its eerie name from mist that rises from the water on cool mornings. The surrounding road has accumulated decades of murder tales, ghost stories and supernatural folklore; visitors should use the designated state-forest parking area rather than stop in traffic.', 'roadside', 'https://www.nj.gov/dep/parksandforests/maps/jennyjump-trail.pdf', null, 'America/New_York', now()),
  ('Devil''s Tree', 'devils-tree', 'folklore', 40.63034, -74.58266, 'Bernards Township', 'NJ', 'A solitary oak in a public park has accumulated stories involving curses, unexplained warmth and supposed hangings. Historical evidence does not support many of the more sensational claims, but the tree remains one of New Jersey''s best-known pieces of local supernatural folklore.', 'open', 'https://www.atlasobscura.com/places/devils-tree', null, 'America/New_York', now()),
  ('Grave of the Unknown Woman', 'grave-of-the-unknown-woman', 'weird-history', 40.61772, -74.28624, 'Rahway', 'NJ', 'In 1887, the body of an unidentified murdered woman was found near Rahway, drawing national attention but never yielding a confirmed identity. Her simple grave survives at the rear of Rahway Cemetery and still bears the mystery in its inscription.', 'open', 'https://www.atlasobscura.com/places/grave-of-the-unknown-woman', null, 'America/New_York', now()),
  ('Matawan Shark Attack Memorial', 'matawan-shark-attack-memorial', 'weird-history', 40.41859, -74.22696, 'Matawan', 'NJ', 'A memorial in Matawan''s Memorial Park remembers Lester Stillwell and Stanley Fisher, who were killed during the 1916 Jersey Shore shark attacks. Their deaths were particularly shocking because the attacks occurred inland in Matawan Creek rather than in the open ocean.', 'open', 'https://www.atlasobscura.com/places/matawan-new-jersey-shark-attack-of-1916', null, 'America/New_York', now()),
  ('Luna Parc', 'luna-parc', 'roadside-oddities', 41.25231, -74.78795, 'Sandyston Township', 'NJ', 'Artist Ricky Boscarino has spent decades transforming his home and studio into a fantastical mosaic-covered environment of towers, color, sculpture and found objects. Because Luna Parc is also a private residence, public access is limited to scheduled open-house events.', 'limited', 'https://www.lunaparc.com/', null, 'America/New_York', now()),
  ('Palace of Depression', 'palace-of-depression', 'roadside-oddities', 39.48414, -75.0612, 'Vineland', 'NJ', 'George Daynor originally built his bizarre "palace" from junk, mud, concrete and discarded materials after losing his fortune during the Great Depression. Volunteers have spent years reconstructing the folk-art landmark; access is restricted and visitors should follow current tour or event information rather than enter uninvited.', 'limited', 'https://www.facebook.com/thepalaceofdepression/', null, 'America/New_York', now()),
  ('Japanese Giant Spider Crab — Rutgers Geology Museum', 'japanese-giant-spider-crab-rutgers-geology-museum', 'museums', 40.49864, -74.44667, 'New Brunswick', 'NJ', 'Rutgers University''s geology museum contains fossils, minerals, dinosaurs and an enormous preserved Japanese spider crab with an extraordinary leg span. The nineteenth-century museum is free, but public hours follow the university''s schedule.', 'limited', 'https://geologymuseum.rutgers.edu/', null, 'America/New_York', now()),
  ('Flexible Flyer Museum', 'flexible-flyer-museum', 'museums', 39.96475, -74.95025, 'Moorestown', 'NJ', 'A small display inside the Moorestown Library preserves the history of Samuel Leeds Allen''s Flexible Flyer, one of America''s most famous sled designs. Vintage sleds, photographs and manufacturing material document the locally invented winter icon.', 'limited', 'https://www.roadsideamerica.com/tip/4852', null, 'America/New_York', now()),
  ('The Sarnoff Collection', 'the-sarnoff-collection', 'museums', 40.27096, -74.77737, 'Ewing Township', 'NJ', 'More than 6,000 artifacts at The College of New Jersey document the history of RCA, radio, television and experimental electronics. Strange prototypes include early electronic displays, obsolete video technologies and equipment tied to major twentieth-century communications breakthroughs; visits are currently by appointment.', 'limited', 'https://davidsarnoff.tcnj.edu/', null, 'America/New_York', now()),
  ('Matchbox Road Museum', 'matchbox-road-museum', 'museums', 39.5458, -75.022, 'Newfield', 'NJ', 'Collector Everett Marshall has assembled an enormous private museum devoted to Matchbox vehicles, with thousands of miniature cars and related material displayed behind his home. Visits are by appointment, making this a legitimate but deliberately limited OddWay stop.', 'limited', 'https://www.facebook.com/MatchboxRoadMuseum', null, 'America/New_York', now()),
  ('Mighty Joe the Gorilla', 'mighty-joe-the-gorilla', 'roadside-oddities', 39.81017, -74.73678, 'Shamong Township', 'NJ', 'A giant fiberglass gorilla towers over Route 206 outside Mighty Joe''s Gas, gripping a sign high above passing traffic. The old-school roadside figure is part of the American tradition of oversized advertising statues and has become a recognizable Pine Barrens landmark.', 'roadside', 'https://www.atlasobscura.com/places/mighty-joe-the-gorilla', null, 'America/New_York', now()),
  ('High Point Monument', 'high-point-monument', 'weird-history', 41.32095, -74.66162, 'Montague Township', 'NJ', 'A 220-foot obelisk crowns New Jersey''s highest point at 1,803 feet above sea level. Dedicated to New Jersey veterans, the monument can be reached through High Point State Park, with interior access and road conditions varying by season.', 'limited', 'https://dep.nj.gov/parksandforests/state-park/high-point-state-park/', null, 'America/New_York', now()),
  ('Franklin Mineral Museum', 'franklin-mineral-museum', 'museums', 41.11361, -74.58889, 'Franklin', 'NJ', 'Franklin sits in one of the world''s most famous fluorescent-mineral districts, and this museum preserves thousands of local mineral specimens along with mining and geology exhibits. Its displays make visible the unusual colors and mineral diversity that earned the area an international reputation.', 'limited', 'https://franklinmineralmuseum.org/', null, 'America/New_York', now()),
  ('InfoAge Science & History Museums — Historic Camp Evans', 'infoage-science-history-museums-historic-camp-evans', 'museums', 40.18596, -74.06158, 'Wall Township', 'NJ', 'The former Camp Evans military research complex now contains more than 20 museums and exhibits devoted to radio, radar, computing, military technology, spaceflight and other scientific history. The site preserves buildings tied to early wireless communication and World War II radar research.', 'limited', 'https://www.infoage.org/', null, 'America/New_York', now()),
  ('Carranza Memorial', 'carranza-memorial', 'weird-history', 39.77734, -74.6321, 'Tabernacle Township', 'NJ', 'Deep in Wharton State Forest, a stone monument marks the 1928 crash site of Mexican aviation hero Emilio Carranza. The roughly 12-foot memorial incorporates an Aztec-inspired design and a falling eagle, turning a remote Pine Barrens clearing into an international aviation memorial.', 'open', 'https://dep.nj.gov/parksandforests/wharton-state-forest/', null, 'America/New_York', now()),
  ('Whitesbog Historic Village', 'whitesbog-historic-village', 'weird-history', 39.95945, -74.50956, 'Pemberton Township', 'NJ', 'This preserved company village grew around cranberry farming and became the site where Elizabeth White and Frederick Coville developed the first cultivated highbush blueberries in the early twentieth century. Historic buildings, bogs and trails remain across the publicly accessible property.', 'open', 'https://whitesbog.org/', null, 'America/New_York', now()),
  ('Double Trouble Village', 'double-trouble-village', 'weird-history', 39.89788, -74.22129, 'Berkeley Township', 'NJ', 'A former Pine Barrens company town survives inside Double Trouble State Park, where cranberry agriculture and Atlantic white-cedar logging once supported a small industrial community. Historic houses, a sawmill and other village structures remain along public trails.', 'open', 'https://dep.nj.gov/parksandforests/state-park/double-trouble-state-park/', null, 'America/New_York', now()),
  ('Long Pond Ironworks', 'long-pond-ironworks', 'weird-history', 41.14525, -74.31178, 'West Milford', 'NJ', 'Ruins of furnaces, waterwheels, stone walls and workers'' buildings survive from an ironmaking community that operated for centuries near the New York border. Public trails weave through the industrial remains, while the museum follows a more limited schedule.', 'open', 'https://longpondironworks.org/', null, 'America/New_York', now()),
  ('Atsion Mansion', 'atsion-mansion', 'weird-history', 39.7425, -74.72611, 'Shamong Township', 'NJ', 'This 1826 Greek Revival mansion was built during Atsion''s ironmaking era in the Pine Barrens. The surrounding settlement largely disappeared, leaving the restored mansion as one of the clearest surviving structures from the old industrial village.', 'limited', 'https://dep.nj.gov/parksandforests/wharton-state-forest/', null, 'America/New_York', now()),
  ('Historic Village at Allaire', 'historic-village-at-allaire', 'weird-history', 40.16149, -74.12707, 'Wall Township', 'NJ', 'Allaire preserves an early nineteenth-century iron-producing company town complete with workers'' homes, workshops, a general store and other village buildings. Demonstrations and scheduled programs interpret the unusual self-contained industrial community that once operated here.', 'limited', 'https://allairevillage.org/', null, 'America/New_York', now()),
  ('Fort Mott', 'fort-mott', 'weird-history', 39.60379, -75.55232, 'Pennsville Township', 'NJ', 'Massive concrete gun batteries remain along the Delaware River from a late nineteenth-century coastal-defense system built to protect approaches to Philadelphia. Visitors can walk among the fortifications and see the disappearing-gun positions from public park grounds.', 'open', 'https://dep.nj.gov/parksandforests/state-park/fort-mott-state-park/', null, 'America/New_York', now()),
  ('Navesink Twin Lights', 'navesink-twin-lights', 'weird-history', 40.39622, -73.98578, 'Highlands', 'NJ', 'Two lighthouse towers joined by a fortress-like building overlook Sandy Hook from the Navesink Highlands. The site played roles in lighthouse technology, early wireless communication and radar history, making it far stranger than a standard coastal light station.', 'limited', 'https://www.twinlightslighthouse.org/', null, 'America/New_York', now()),
  ('Sandy Hook Lighthouse', 'sandy-hook-lighthouse', 'weird-history', 40.46173, -74.00202, 'Middletown Township', 'NJ', 'First lit in 1764, Sandy Hook Lighthouse is the oldest continuously operating lighthouse in the United States. The tower stands inside the Fort Hancock area of Gateway National Recreation Area, with scheduled ranger access to the interior.', 'limited', 'https://www.nps.gov/gate/learn/historyculture/sandy-hook-lighthouse.htm', null, 'America/New_York', now()),
  ('Sandy Hook Nike Missile Radar Site', 'sandy-hook-nike-missile-radar-site', 'weird-history', 40.44895, -73.9927, 'Middletown Township', 'NJ', 'Surviving radar structures mark part of the Cold War Nike missile system that once defended the New York metropolitan area from air attack. The National Park Service still offers occasional guided tours of this former top-secret radar and guidance site near Horseshoe Cove.', 'limited', 'https://www.nps.gov/planyourvisit/event-details.htm?id=67AA9F42-DF76-6986-CA7F9F2192CABADB', null, 'America/New_York', now()),
  ('World War II Bunker at Cape May Point', 'world-war-ii-bunker-at-cape-may-point', 'weird-history', 38.93284, -74.96077, 'Lower Township', 'NJ', 'A huge concrete coastal-defense bunker sits directly on the beach, where shoreline erosion gradually moved it from its original inland position toward the surf. Built during World War II, the structure is now one of Cape May Point''s most conspicuous military ruins.', 'open', 'https://www.atlasobscura.com/places/cape-may-bunker', null, 'America/New_York', now()),
  ('Emlen Physick Estate', 'emlen-physick-estate', 'haunted', 38.94034, -74.91478, 'Cape May', 'NJ', 'This 1879 Victorian mansion is preserved as a house museum filled with period architecture and furnishings. Cape May MAC also incorporates the estate into ghost-themed programming built around local reports and legends associated with the property.', 'limited', 'https://capemaymac.org/experience/emlen-physick-estate/', null, 'America/New_York', now()),
  ('Cape May Lighthouse', 'cape-may-lighthouse', 'weird-history', 38.93299, -74.96037, 'Lower Township', 'NJ', 'The 1859 Cape May Lighthouse rises 157 feet above the southern New Jersey coast and can be climbed by visitors during operating hours. Its 199 steps lead to a panoramic view over Cape May Point State Park and the surrounding shoreline.', 'limited', 'https://capemaymac.org/experience/cape-may-lighthouse/', null, 'America/New_York', now()),
  ('Naval Air Station Wildwood Aviation Museum', 'naval-air-station-wildwood-aviation-museum', 'museums', 39.00509, -74.90972, 'Lower Township', 'NJ', 'A preserved World War II hangar houses aircraft, engines, military vehicles and aviation artifacts at the former Naval Air Station Wildwood. The setting gives visitors access to both the collection and an authentic wartime training structure.', 'limited', 'https://usnasw.org/', null, 'America/New_York', now()),
  ('New Jersey Maritime Museum', 'new-jersey-maritime-museum', 'museums', 39.56613, -74.24433, 'Beach Haven', 'NJ', 'This shore museum concentrates on New Jersey shipwrecks, maritime disasters, diving and coastal history. Displays include artifacts recovered from wrecks and extensive research material on vessels lost along the state''s notoriously dangerous coastline.', 'limited', 'https://njmaritimemuseum.org/', null, 'America/New_York', now()),
  ('Millville Army Air Field Museum', 'millville-army-air-field-museum', 'museums', 39.37199, -75.07248, 'Millville', 'NJ', 'Millville''s wartime airfield trained thousands of fighter pilots during World War II. The museum preserves aircraft, uniforms, photographs and personal stories from the base, including the dangerous training work that earned Millville its place in military aviation history.', 'limited', 'https://p47millville.org/', null, 'America/New_York', now()),
  ('WheatonArts — Museum of American Glass', 'wheatonarts-museum-of-american-glass', 'museums', 39.4106, -75.02057, 'Millville', 'NJ', 'The Museum of American Glass preserves thousands of examples of American glassmaking inside a larger arts complex rooted in southern New Jersey''s glass industry. Furnaces and artist demonstrations help connect unusual historic objects with the techniques used to create them.', 'limited', 'https://www.wheatonarts.org/', null, 'America/New_York', now()),
  ('Heritage Glass Museum', 'heritage-glass-museum', 'museums', 39.70267, -75.11067, 'Glassboro', 'NJ', 'Glassboro''s name reflects the industry that shaped the community, and this small museum preserves bottles, tools and locally manufactured glass from that history. Its specialized collection gives travelers a compact look at an industry that once dominated the region.', 'limited', 'https://www.glassborohistory.org/', null, 'America/New_York', now()),
  ('Roebling Museum', 'roebling-museum', 'museums', 40.11865, -74.77318, 'Roebling', 'NJ', 'The former John A. Roebling''s Sons factory site interprets the wire-rope company responsible for material used in famous suspension bridges including the Brooklyn and Golden Gate bridges. Industrial machinery, photographs and factory artifacts survive inside the company-town museum.', 'limited', 'https://www.roeblingmuseum.org/', null, 'America/New_York', now()),
  ('Paterson Museum', 'paterson-museum', 'museums', 40.91348, -74.17882, 'Paterson', 'NJ', 'Housed in the former Rogers Locomotive Works, the Paterson Museum preserves locomotives, industrial machinery, Colt firearms, minerals and objects tied to the city''s manufacturing history. The eclectic collection reflects how many different industries once clustered around the Great Falls.', 'limited', 'https://www.patersonnj.gov/department/division.php?structureid=16', null, 'America/New_York', now()),
  ('Paterson Great Falls', 'paterson-great-falls', 'weird-history', 40.91533, -74.17992, 'Paterson', 'NJ', 'A 77-foot waterfall in the middle of Paterson powered Alexander Hamilton''s planned industrial city and generations of mills and factories. Today the natural spectacle and surviving industrial landscape are protected as a National Historical Park.', 'open', 'https://www.nps.gov/pagr/', null, 'America/New_York', now()),
  ('Tripod Rock', 'tripod-rock', 'roadside-oddities', 40.95189, -74.39186, 'Kinnelon', 'NJ', 'An enormous glacial boulder appears improbably balanced on three much smaller stones at Pyramid Mountain. The formation is natural, but its precise-looking supports have inspired repeated speculation about whether people altered or used it in the distant past.', 'open', 'https://www.atlasobscura.com/places/tripod-rock', null, 'America/New_York', now()),
  ('South Mountain Fairy Trail', 'south-mountain-fairy-trail', 'folklore', 40.72657, -74.30478, 'Millburn Township', 'NJ', 'Tiny handmade doors, houses and miniature scenes appear along a wooded trail in South Mountain Reservation. The installations turn an ordinary family hike into a search for a hidden fairy village tucked into roots, trunks and rocks.', 'open', 'https://www.atlasobscura.com/places/south-mountain-fairy-trail', null, 'America/New_York', now()),
  ('Van Slyke Castle Ruins', 'van-slyke-castle-ruins', 'weird-history', 41.04486, -74.26278, 'Ringwood', 'NJ', 'Stone walls, foundations and a large swimming-pool ruin remain from a mansion that once stood high above the Wanaque Reservoir. Fire destroyed the house in the 1950s, and the legal public trail now leads hikers through the atmospheric remains.', 'open', 'https://www.atlasobscura.com/places/van-slyke-castle', null, 'America/New_York', now()),
  ('Camp No-Be-Bo-Sco — Camp Crystal Lake', 'camp-no-be-bo-sco-camp-crystal-lake', 'weird-history', 41.05596, -74.94877, 'Hardwick Township', 'NJ', 'This active Scout camp served as the primary filming location for the original 1980 Friday the 13th, standing in for Camp Crystal Lake. It is private property and closed to casual visitors, but officially sanctioned Crystal Lake Tours provide limited public access on specific dates.', 'limited', 'https://crystallaketours.com/', null, 'America/New_York', now()),
  ('Central Railroad of New Jersey Terminal', 'central-railroad-of-new-jersey-terminal', 'weird-history', 40.70721, -74.03519, 'Jersey City', 'NJ', 'Millions of immigrants who had entered the United States through nearby Ellis Island continued their journeys through this enormous waterfront railroad terminal. The restored train sheds and terminal building survive inside Liberty State Park as a striking transportation ruin-turned-historic site.', 'open', 'https://www.nps.gov/places/000/central-railroad-of-new-jersey-terminal.htm', null, 'America/New_York', now()),
  ('The Colgate Clock', 'the-colgate-clock', 'roadside-oddities', 40.71203, -74.03389, 'Jersey City', 'NJ', 'A massive octagonal clock faces Manhattan from the Jersey City waterfront, surviving from the former Colgate-Palmolive factory complex. Its enormous illuminated face has remained a local landmark even after most of the industrial site around it disappeared.', 'open', 'https://www.atlasobscura.com/places/colgate-clock', null, 'America/New_York', now()),
  ('Sybil''s Cave', 'sybils-cave', 'weird-history', 40.74533, -74.02298, 'Hoboken', 'NJ', 'A stone portal along the Hoboken waterfront recreates the entrance to a nineteenth-century spring grotto once promoted for its supposedly healthful water. The original cave also became connected with a notorious unsolved murder after the 1841 death of Mary Rogers.', 'open', 'https://www.atlasobscura.com/places/sybils-cave', null, 'America/New_York', now()),
  ('Lower Trenton Bridge — TRENTON MAKES Sign', 'lower-trenton-bridge-trenton-makes-sign', 'roadside-oddities', 40.21037, -74.76907, 'Trenton', 'NJ', 'The Delaware River bridge carries the enormous illuminated slogan ''TRENTON MAKES THE WORLD TAKES,'' first created to advertise the city''s manufacturing power. The blunt industrial boast remains one of New Jersey''s most recognizable pieces of infrastructure lettering.', 'open', 'https://www.atlasobscura.com/places/trenton-makes-the-world-takes-bridge', null, 'America/New_York', now()),
  ('Arthur Kill Vertical Lift Bridge', 'arthur-kill-vertical-lift-bridge', 'roadside-oddities', 40.63757, -74.19565, 'Elizabeth', 'NJ', 'This enormous railroad lift bridge raises its center span hundreds of feet to allow ships through the Arthur Kill between New Jersey and Staten Island. It remains an active piece of rail infrastructure and should only be viewed from legitimate public vantage points rather than approached on the tracks.', 'roadside', 'https://www.atlasobscura.com/places/arthur-kill-vertical-lift-bridge', null, 'America/New_York', now()),
  ('Telephone Pole Farm', 'telephone-pole-farm', 'roadside-oddities', 40.79402, -74.6682, 'Chester Township', 'NJ', 'Rows of old utility poles stand upright in an open field at Highlands Ridge Park, creating the eerie appearance of a forest made entirely from telephone infrastructure. The unusual landscape is publicly accessible within the park.', 'open', 'https://www.atlasobscura.com/places/telephone-pole-farm', null, 'America/New_York', now()),
  ('Victor Victori''s Multiplism Statues', 'victor-victoris-multiplism-statues', 'roadside-oddities', 40.82578, -74.10561, 'Rutherford', 'NJ', 'Artist Victor Victori filled the lawn around his home with a crowd of expressive white figures tied to his ''multiplism'' style. The sculptures are on private residential property, so travelers should view them only from the public sidewalk or street.', 'roadside', 'https://www.roadsideamerica.com/tip/13376', null, 'America/New_York', now()),
  ('Evans-Ellis Cemetery', 'evans-ellis-cemetery', 'weird-history', 40.4892, -74.41658, 'North Brunswick Township', 'NJ', 'A tiny family cemetery survives in an unlikely island of grass beside modern commercial development. Old headstones belonging to early local families remain surrounded by the infrastructure that grew up around the once-rural burial ground.', 'limited', 'https://www.atlasobscura.com/places/evans-ellis-cemetery', null, 'America/New_York', now()),
  ('Little Lost Cemetery', 'little-lost-cemetery', 'weird-history', 40.86732, -74.41633, 'Parsippany-Troy Hills', 'NJ', 'A handful of old gravestones survive behind a modern firehouse, almost completely disconnected from the landscape in which the cemetery was created. Its isolation amid later development gives the tiny burial ground its ''lost'' character.', 'limited', 'https://www.atlasobscura.com/places/little-lost-cemetery', null, 'America/New_York', now()),
  ('Jersey City and Harsimus Cemetery', 'jersey-city-and-harsimus-cemetery', 'weird-history', 40.72717, -74.05517, 'Jersey City', 'NJ', 'Founded in 1829, this sprawling historic cemetery contains old crypts, hillside graves and layers of Jersey City history. In recent years goats have also been used seasonally to control invasive vegetation, adding an unusual living element to the preservation work.', 'limited', 'https://www.jerseycitycemetery.org/', null, 'America/New_York', now()),
  ('Clara Glen Pet Cemetery', 'clara-glen-pet-cemetery', 'weird-history', 39.33191, -74.58293, 'Egg Harbor Township', 'NJ', 'Weathered stones mark the graves of dogs and other pets in a small, easily overlooked burial ground surrounded by later residential development. The cemetery should be observed respectfully from legitimate public access without crossing neighboring private property.', 'roadside', 'https://www.atlasobscura.com/places/clara-glen-pet-cemetery', null, 'America/New_York', now()),
  ('Doris Duke''s Pet Cemetery', 'doris-dukes-pet-cemetery', 'weird-history', 40.54433, -74.62393, 'Hillsborough Township', 'NJ', 'Heiress Doris Duke buried a number of beloved dogs and other animals on her vast Duke Farms estate. Their individual markers form an unusual private-animal cemetery that can be reached only according to Duke Farms'' public access rules and trail hours.', 'limited', 'https://www.atlasobscura.com/places/doris-dukes-pet-cemetery', null, 'America/New_York', now()),
  ('Grave of Sinbad the Coast Guard Dog', 'grave-of-sinbad-the-coast-guard-dog', 'weird-history', 39.75812, -74.10344, 'Barnegat Light', 'NJ', 'Sinbad served aboard the Coast Guard cutter Campbell for years, surviving combat and becoming one of the service''s most famous animal mascots. A memorial and burial site at Barnegat Light preserves the story of the mixed-breed dog whose service career included World War II.', 'limited', 'https://www.history.uscg.mil/Browse-by-Topic/Assets/Land/All/Article/1882479/sinbad-the-coast-guard-dog/', null, 'America/New_York', now()),
  ('Dryptosaurus Skeletal Mount', 'dryptosaurus-skeletal-mount', 'museums', 40.22107, -74.77309, 'Trenton', 'NJ', 'The New Jersey State Museum displays a skeletal reconstruction of Dryptosaurus, a large predatory dinosaur first discovered in the state. The mount gives physical form to a dinosaur whose fossils helped shape early American paleontology.', 'limited', 'https://www.nj.gov/state/museum/explore-natural-history.shtml', null, 'America/New_York', now()),
  ('Princeton Chapel Bulldog', 'princeton-chapel-bulldog', 'roadside-oddities', 40.34871, -74.65739, 'Princeton', 'NJ', 'Among the Gothic details of Princeton University Chapel is a small bulldog incorporated into the stonework, reportedly a playful reference to rival Yale''s mascot. Finding the hidden animal turns the massive chapel exterior into an architectural scavenger hunt.', 'open', 'https://www.atlasobscura.com/places/princeton-chapel-bulldog', null, 'America/New_York', now()),
  ('Lawrence Brook Carvings', 'lawrence-brook-carvings', 'roadside-oddities', 40.47342, -74.42274, 'New Brunswick', 'NJ', 'Faces and figures carved into stone appear near Lawrence Brook within the Rutgers Gardens area. The weathered carvings are easy to miss among the landscape and are accessible only during the gardens'' normal public hours.', 'limited', 'https://www.atlasobscura.com/places/lawrence-brook-carvings', null, 'America/New_York', now()),
  ('Hoopar Brothers Gravestone', 'hoopar-brothers-gravestone', 'weird-history', 40.50042, -74.39606, 'Piscataway', 'NJ', 'An unusual double gravestone commemorates two young brothers and uses striking carved imagery characteristic of early American funerary art. It survives in the historic Piscatawaytown Burial Ground beside St. James Church.', 'open', 'https://www.atlasobscura.com/places/hoopar-brothers-gravestone', null, 'America/New_York', now()),
  ('Black Tom Explosion Memorial', 'black-tom-explosion-memorial', 'weird-history', 40.69221, -74.05605, 'Jersey City', 'NJ', 'A memorial in Liberty State Park recalls the massive 1916 Black Tom explosion, when German agents sabotaged munitions stored on the New Jersey waterfront before the United States entered World War I. The blast shattered windows miles away and damaged the Statue of Liberty.', 'open', 'https://www.nps.gov/articles/black-tom-explosion.htm', null, 'America/New_York', now()),
  ('Katyń Massacre Memorial', 'katyn-massacre-memorial', 'weird-history', 40.71626, -74.03298, 'Jersey City', 'NJ', 'A dramatic bronze soldier pierced by a bayonet stands at Exchange Place as a memorial to Polish officers and others murdered by the Soviet secret police during the 1940 Katyń massacres. The disturbing imagery makes the monument intentionally difficult to ignore.', 'open', 'https://www.atlasobscura.com/places/katyn-massacre-memorial', null, 'America/New_York', now()),
  ('Stern Plate of the USS Enterprise', 'stern-plate-of-the-uss-enterprise', 'weird-history', 41.00794, -74.01057, 'River Vale', 'NJ', 'A large steel stern plate bearing the name ENTERPRISE survives from the World War II aircraft carrier USS Enterprise, one of the most decorated U.S. Navy ships of the conflict. The relic is displayed as part of the township''s veterans memorial.', 'open', 'https://www.roadsideamerica.com/tip/15144', null, 'America/New_York', now()),
  ('The Spot Where World War I Ended', 'the-spot-where-world-war-i-ended', 'weird-history', 40.57698, -74.63143, 'Bridgewater Township', 'NJ', 'A small plaque marks the location where a local false report of the armistice triggered an early celebration on November 7, 1918, four days before the actual end of fighting. The episode became one of the strangest American footnotes to the close of World War I.', 'roadside', 'https://www.roadsideamerica.com/tip/12535', null, 'America/New_York', now())
on conflict (slug) do update set
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  website       = excluded.website,
  verified_at   = excluded.verified_at;

select count(*) as new_jersey from public.stops where state = 'NJ';
